def Levenshtein(a,b):
    if len(a)<len(b):
        return Levenshtein(b,a)
    if len(b)==0:
        return len(a)
    previous = list(range(len(b)+1))
    for ca in a:
        current = [previous[0]+1]
        for j,cb in enumerate(b):
            current.append(min(current[j]+1,previous[j+1]+1,previous[j]+(ca!=cb)))
        previous = current
    return previous[-1]

