def _Dir(pts,fromEnd,n=4):
    p = np.asarray(pts,np.float64)
    if fromEnd:
        a,b = p[max(0,len(p)-1-n)],p[-1]
    else:
        a,b = p[min(len(p)-1,n)],p[0]
    v = b-a
    L = np.hypot(*v)
    return v/L if L>1e-6 else np.array([1.0,0.0])

