def _PruneSpurs(chains,minLen=2.5):
    if len(chains)<=1:
        return chains
    ends = {}
    for c in chains:
        for e in (tuple(c[0]),tuple(c[-1])):
            ends[e] = ends.get(e,0)+1
    out = []
    for c in chains:
        L = PolylineLength(c)
        dangling = ends[tuple(c[0])]==1 or ends[tuple(c[-1])]==1
        if L<minLen and dangling and len(chains)>1:
            continue
        out.append(c)
    return out or chains

