def _AlignStroke(s,N):
    s = np.asarray(s,float)
    if len(s)<2:
        return None
    if float(np.hypot(*(s[0]-s[-1])))<0.30 and len(s)>=4:
        i0 = int(np.argmin(s[:,0]))
        s = np.concatenate([s[i0:],s[:i0+1]])
    elif s[0,0]>s[-1,0]:
        s = s[::-1]
    return _ResampleN(s,N)

