def ExtractAuthorRaw(authorId,lineItems,model):
    parsed = []
    for gray,text in lineItems:
        glyphs,stats = ExtractLineGlyphs(gray,text,model)
        if glyphs is not None:
            stats = dict(stats)
            stats['ref'] = RenderRefStats(gray)
