def ClusterRows(rows,maxGap=5):
    rows = np.asarray(sorted(rows),dtype=np.int64)
    if rows.size==0:
        return []
    cut = np.nonzero(np.diff(rows)>maxGap)[0]+1
    return [int(g.mean()) for g in np.split(rows,cut) if g.size]

