def LoadParamsInto(params,checkpointPath):
    sd,_ = CLS.LoadStateDictAny(checkpointPath)
    loaded = 0
    for k in params:
        if k in sd and sd[k].shape==params[k].shape:
            params[k][...] = sd[k].astype(np.float32)
            loaded+=1
    return loaded

