def _GetLock():
    global _previewLock
    if _previewLock is None:
        import threading
        _previewLock = threading.Lock()
    return _previewLock

def PreviewStop():
    global _previewCap
    with _GetLock():
        if _previewCap is not None:
            _previewCap.release()
            _previewCap = None

def PreviewFrameJpeg():
    import cv2
    with _GetLock():
        if _previewCap is None:
            raise RuntimeError("Preview not started -- call preview_start() first.")
        ok,frame = _previewCap.read()
    if not ok:
        raise RuntimeError("Failed to read a preview frame.")
    ok,buf = cv2.imencode(".jpg",frame)
    if not ok:
        raise RuntimeError("Failed to JPEG-encode preview frame.")
    return buf.tobytes()

def CaptureImage(timeout=10,index=None):
    import cv2

    with _GetLock():
        if _previewCap is not None:
            ok,frame = _previewCap.read()
            if not ok:
                raise RuntimeError("Failed to read a frame from the open preview.")
            outPath = CAPTURE_DIR/f"capture_{int(time.time()*1000)}.jpg"
            cv2.imwrite(str(outPath),frame)
            return outPath

    idx = CAMERA_INDEX if index is None else index
    cap = cv2.VideoCapture(idx)
    if not cap.isOpened():
        cap.release()
        raise RuntimeError(
            f"Could not open camera at index {idx}. Is it plugged in, and "
            "not already in use by another program (close any other app "
            "using the webcam, e.g. a video call)?"
        )

    deadline = time.time()+timeout
    frame = None
    try:
        for _ in range(WARMUP_FRAMES):
            if time.time()>deadline:
                break
            ok,frame = cap.read()
            if not ok:
                frame = None
    finally:
        cap.release()

    if frame is None:
        raise RuntimeError(
            f"Camera at index {idx} opened but produced no readable frame "
            "within the timeout."
        )

    outPath = CAPTURE_DIR/f"capture_{int(time.time()*1000)}.jpg"
    cv2.imwrite(str(outPath),frame)
    if not outPath.exists():
        raise RuntimeError(f"cv2.imwrite reported no error but wrote no file: {outPath}")
    return outPath

def CanPool(n):
    return (LINE_WORKERS != 1 and n >= MIN_LINES_FOR_POOL
            and hasattr(os, "fork") and bool(_CFG))

def _Workers(n):
    if LINE_WORKERS > 0:
        return min(LINE_WORKERS, n)
    return max(1, min(os.cpu_count() or 1, n))

def Map(fn, jobs):
    jobs = list(jobs)
    if not jobs:
        return []
    if not CanPool(len(jobs)):
        return [fn(j) for j in jobs]
    try:
        import multiprocessing as mp
        ctx = mp.get_context("fork")
        with ctx.Pool(processes=_Workers(len(jobs)), initializer=_Init) as pool:
            out = pool.map(fn, jobs, chunksize=1)
        return out
    except Exception as e:
        print("[lineworkers] pool unavailable (%s), running in one process"
              % type(e).__name__, file=sys.stderr, flush=True)
        return [fn(j) for j in jobs]

def _font(size,bold=False):
    key = (size,bold)
    if key not in _FONT_CACHE:
        name = "consolab.ttf" if bold else "consola.ttf"
        try:
            _FONT_CACHE[key] = ImageFont.truetype(f"C:/Windows/Fonts/{name}",size)
        except Exception:
            _FONT_CACHE[key] = ImageFont.load_default()
    return _FONT_CACHE[key]

def _RenderOneGlyph(g,cell=90,pad=8):
    strokes = g.get("strokes",[])
    im = Image.new("L",(cell,cell),255)
    draw = ImageDraw.Draw(im)
    allpts = [p for s in strokes for p in s]
    if not allpts:
        return im
    xs = [p[0] for p in allpts]
    ys = [p[1] for p in allpts]
    x0,x1,y0,y1 = min(xs),max(xs),min(ys),max(ys)
    w = max(x1-x0,0.01)
    h = max(y1-y0,0.01)
    scale = (cell-2*pad)/max(w,h)

    def tx(p):
        return (pad+(p[0]-x0)*scale,cell-pad-(p[1]-y0)*scale)

    for s in strokes:
        pts = [tx(p) for p in s]
        if len(pts)>=2:
            draw.line(pts,fill=0,width=2)
    return im

def SampleCrops(author,n=2):
    metaPath = CACHE_DIR/f"sample_{author}_meta.txt"
    cached = sorted(CACHE_DIR.glob(f"sample_{author}_*.png"))
    if len(cached)>=n and metaPath.exists():
        texts = metaPath.read_text(encoding="utf-8").splitlines()
        return list(zip(cached[:n],texts[:n]))

    import numpy as np
    from PIL import Image
    import train as TR

    base = TR.IAMLineDatasetRaw(rootDir=str(TR.DEFAULT_AUTHOR_DATA_DIR),
                                cacheDir=str(TR.DEFAULT_AUTHOR_CACHE_DIR))
    if author in paths.DatabaseWriters:
        base.samples = [s for s in base.samples
                        if s["page_key"].split("/")[0]==author]
    else:
        base.samples = []
        TR.AddPersonalSamples(base)
        base.samples = [s for s in base.samples
                        if s["page_key"].split("/")[0]==author]

    picked = []
    for s in base.samples:
        if s.get("is_holdout"):
            continue
        if 20<=len(s["text"])<=70:
            picked.append(s)
        if len(picked)>=n:
            break

    outPaths,texts = [],[]
    for i,s in enumerate(picked):
        arr = TR.DecodeCrop(s["imageBytes"])
        path = CACHE_DIR/f"sample_{author}_{i}.png"
        Image.fromarray(np.asarray(arr,dtype=np.uint8)).convert("L").save(path)
        outPaths.append(path)
        texts.append(s["text"])
    metaPath.write_text("\n".join(texts),encoding="utf-8")
    return list(zip(outPaths,texts))

def LoadProfiles():
    out = {}
    for f in sorted(paths.Profiles.glob("*.json")):
        try:
            out[f.stem] = json.load(open(f, encoding="utf-8"))
        except Exception as e:
            print("[server] skipping profile %s: %s" % (f.name, e))
    return out

def CheckApiKey():
    if API_KEY and request.headers.get("X-API-Key") != API_KEY:
        abort(401)

def Static(name):
    if (FRONTEND/name).exists():
        return send_from_directory(FRONTEND, name)
    abort(404)

def ApiAuthors():
    out = []
    for a in sorted(PROFILES):
        p = PROFILES[a]
        out.append(dict(id=a,
                        glyphs=len(p.get("glyphs") or {}),
